-- ============================================================================
-- Room Scheduling Tracker — SQLite schema (local demo / tests only)
-- Same tables and columns as database/rst_db.sql, with SQLite-compatible
-- types. MySQL remains the production database (see rst_db.sql).
-- Usage:
--   DB_DRIVER=sqlite DB_PATH=storage/rst.db php -S localhost:8000 -t public
--   sqlite3 storage/rst.db < database/sqlite_schema.sql
--   sqlite3 storage/rst.db < database/sqlite_seed.sql   (generated by tests)
-- ============================================================================
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS tblUsers (
  user_id       INTEGER PRIMARY KEY AUTOINCREMENT,
  username      VARCHAR(50)  NOT NULL UNIQUE,
  email         VARCHAR(255) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  profile_img   VARCHAR(255),
  role          VARCHAR(30)  NOT NULL DEFAULT 'student',
  section       VARCHAR(50),
  org_name      VARCHAR(100),
  phone_number  VARCHAR(17)
);

CREATE TABLE IF NOT EXISTS tblMaps (
  map_id           INTEGER PRIMARY KEY AUTOINCREMENT,
  map_name         VARCHAR(100) NOT NULL,
  floor_number     INTEGER NOT NULL,
  map_width        DECIMAL(10,2) NOT NULL,
  map_height       DECIMAL(10,2) NOT NULL,
  background_image VARCHAR(255),
  map_status       VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS tblRooms (
  room_id          INTEGER PRIMARY KEY AUTOINCREMENT,
  map_id           INTEGER NOT NULL REFERENCES tblMaps(map_id) ON DELETE CASCADE ON UPDATE CASCADE,
  room_name        VARCHAR(100) NOT NULL,
  shape_type       VARCHAR(20)  NOT NULL DEFAULT 'rectangle',
  shape_data       TEXT NOT NULL,
  room_description VARCHAR(255),
  room_status      VARCHAR(20)  NOT NULL DEFAULT 'active',
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (map_id, room_name)
);

CREATE TABLE IF NOT EXISTS tblSchedules (
  schedule_id          INTEGER PRIMARY KEY AUTOINCREMENT,
  organizer_id         INTEGER NOT NULL REFERENCES tblUsers(user_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  room_id              INTEGER NOT NULL REFERENCES tblRooms(room_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  schedule_title       VARCHAR(150) NOT NULL,
  schedule_description TEXT,
  recurrence_type      VARCHAR(20) NOT NULL DEFAULT 'one_time',
  start_date           DATE NOT NULL,
  end_date             DATE,
  start_time           TIME NOT NULL,
  end_time             TIME NOT NULL,
  schedule_status      VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (end_time > start_time)
);

CREATE TABLE IF NOT EXISTS tblScheduleDays (
  schedule_day_id INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_id     INTEGER NOT NULL REFERENCES tblSchedules(schedule_id) ON DELETE CASCADE ON UPDATE CASCADE,
  day_of_week     INTEGER NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),
  UNIQUE (schedule_id, day_of_week)
);

CREATE TABLE IF NOT EXISTS tblScheduleExceptions (
  exception_id     INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_id      INTEGER NOT NULL REFERENCES tblSchedules(schedule_id) ON DELETE CASCADE ON UPDATE CASCADE,
  original_date    DATE NOT NULL,
  exception_type   VARCHAR(20) NOT NULL,
  new_date         DATE,
  new_room_id      INTEGER REFERENCES tblRooms(room_id) ON DELETE SET NULL ON UPDATE CASCADE,
  new_start_time   TIME,
  new_end_time     TIME,
  exception_reason VARCHAR(255),
  created_by       INTEGER NOT NULL REFERENCES tblUsers(user_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (schedule_id, original_date)
);

CREATE TABLE IF NOT EXISTS tblScheduleOccurrences (
  occurrence_id     INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_id       INTEGER NOT NULL REFERENCES tblSchedules(schedule_id) ON DELETE CASCADE ON UPDATE CASCADE,
  occurrence_date   DATE NOT NULL,
  room_id           INTEGER NOT NULL REFERENCES tblRooms(room_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  start_time        TIME NOT NULL,
  end_time          TIME NOT NULL,
  occurrence_status VARCHAR(20) NOT NULL DEFAULT 'scheduled',
  UNIQUE (schedule_id, occurrence_date, room_id, start_time),
  CHECK (end_time > start_time)
);

CREATE INDEX IF NOT EXISTS idx_occurrences_room_date ON tblScheduleOccurrences(room_id, occurrence_date, start_time);
CREATE INDEX IF NOT EXISTS idx_occurrences_date ON tblScheduleOccurrences(occurrence_date);
CREATE INDEX IF NOT EXISTS idx_schedules_room_dates ON tblSchedules(room_id, start_date, end_date);
